REM {Il faut utiliser une vue dans laquelle une colonne contient les UNIDs};
v_Cle :=Tabl_Nom;
v_NomVue := "V_Tabl20";
v_NoColonneUNID := 9;

@If(v_Cle = NULL; @Return(@Failure("Le nom est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; v_Cle; v_NoColonneUNID);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("La table est déjà définie."))

v_NomTable := "Cale_Statut" + SF_Langue;
v_Cle := Cale_Statut;

@TextToNumber(@Replace(v_Cle; @IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 4); ""); @Text(@IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 10); 0))))

v_GDK := @Subset(@DbName; 1) : "SI_GDK.nsf";
v_NomTable := "SDS_DepartementsFR";
v_Cle := Sond_ContactDepartement;

@If(@IsNull(v_Cle); ""; @Replace(v_Cle; @IfError(@DbLookup(""; v_GDK; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup(""; v_GDK; "V_Tabl20"; v_NomTable; 5); "")))

v_Cle := @ThisValue;
v_NomVue := "V_TypI20";

@If(v_Cle = NULL; @Return(@Failure("Le type d'intervention est obligatoire.")); "");
v_Lookup := @DbLookup("" : "NoCache"; ""; v_NomVue; v_Cle; 1; [ReturnDocumentUniqueID]);
@If(@IsError(v_Lookup); @Success; @Elements(v_Lookup) = 1 & v_Lookup = @Text(@DocumentUniqueID); @Success; @Failure("Le type d'intervention est déjà défini."))

v_Msgs:=@DbLookup("Notes":"NoCache"; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_SIMs2"; "SDSI"; 2);
v_Code:=@Left(v_Msgs;" - ");
V_Text:=@Right(v_Msgs;" - ");
v_Posi:=@Member("0009";v_Code);
v_Resu:=@If(v_Posi<=0;"";@Subset(@Subset(V_Text;v_Posi);-1));
v_Titr:=@If(@IsError(v_Resu);"";v_Resu);
v_Posi:=@Member("0010";v_Code);
v_Resu:=@If(v_Posi<=0;"";@Subset(@Subset(V_Text;v_Posi);-1));
v_Info:=@If(@IsError(v_Resu);"";v_Resu);

v_Resu:=@DbLookup("" : "NoCache"; ""; "V_Inte10"; Inst_NoInstallation ; "Inte_TypeInterventionDescFR");
v_Type:=@If(@IsError(v_Resu);"";v_Resu);
v_Resu:=@DbLookup("" : "NoCache"; ""; "V_Inte10"; Inst_NoInstallation ; "Inte_IdIntervenant");
v_Noms:=@If(@IsError(v_Resu);"";v_Resu);

@If(v_Type="";v_Resu:="";v_Resu:=@Prompt([OkCancelListMult];v_Titr;v_Info;"";@Sort(@Unique(v_Type))));
v_Sele:=@If(@IsError(v_Resu) | @Text(v_Resu)="1";"";v_Resu);

v_Resu := "";
@For(n := 1; n <= @Elements(v_Type);n := n + 1;
	v_Resu := v_Resu : @If(v_Type[n] *= v_Sele ; @Name([Abbreviate];v_Noms[n]) ; ""));
v_Dest:=@If(@IsError(v_Resu);"";@Sort(@Unique(@Trim(v_Resu))));

@Command( [MailComposeMemo] );
@Command( [EditInsertText]; @Implode(v_Dest;", "));
@Command( [EditGotoField]; "Subject")

v_NomTable := Inst_StatutTable_1 + SF_Langue;
v_Cle := Inst_Statut;

@TextToNumber(@Replace(v_Cle; @IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 4); ""); @Text(@IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 10); 0))))

v_NomTable := Inst_StatutTable_1 + "FR";
v_Cle := Inst_Statut;

@Replace(v_Cle; @IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 5); ""))

v_NomTable := Inst_StatutTable_1 + "EN";
v_Cle := Inst_Statut;

@Replace(v_Cle; @IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 4); ""); @IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 5); ""))

v_Ville := @If(@IsNull(Inst_ClientNoFmt); ""; @DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Inst_ClientNoFmt; 5; [FailSilent]));
v_Province := @If(@IsNull(Inst_ClientNoFmt); ""; @DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Inst_ClientNoFmt; 8; [FailSilent]));
@Trim(Inst_ClientNomInterne : (v_Ville + "  " + v_Province))

v_NomTable := "Merl_Versions" + SF_Langue;
v_Cle := Inst_65_Version;
v_Valeurs := @DbLookup(""; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 4);
v_Descriptions := @DbLookup(""; @Subset(@DbName; 1) : "SI_GDK.nsf"; "V_Tabl20"; v_NomTable; 5);

@If(@IsNull(v_Cle) | @IsError(v_Valeurs) | @IsNull(v_Valeurs) | @IsNull(v_Descriptions) | @IsError(v_Descriptions); ""; @Replace(v_Cle; v_Valeurs; v_Descriptions))

v_NomTable := "Inst_Type" + SF_Langue;
v_Cle := Inst_TypeInstallation;

@TextToNumber(@Replace(v_Cle; @IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 4); ""); @Text(@IfError(@DbLookup(""; ""; "V_Tabl20"; v_NomTable; 10); 0))))

REM {***** Validations de base};
@If(Inst_ClientNo1 = ""; @Return(@Success); !@Matches(Inst_ClientNo2; "{0123456789}{0123456789}{0123456789}"); @Return(@Failure("La deuxième partie du numéro de client est invalide.")); "");

v_VueSICl := "V_Clie20";
v_CleSICl := @Text(Inst_ClientNo1) + "-" + Inst_ClientNo2;

REM {***** Vérifier l'existence du document};
@If(@IsError(@DbLookup("" : "NoCache"; SF_ServeurSICl : SF_FichierSICl; v_VueSICl; v_CleSICl; 1)); @Return(@Failure("Le client est inexistant.")); @Success)

v_Adresse1 := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Inst_ClientNoFmt; 3); "");
v_Adresse2 := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Inst_ClientNoFmt; 4); "");
v_Ville := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Inst_ClientNoFmt; 5); "");
v_Province := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Inst_ClientNoFmt; 8); "");
v_CodePostal := @IfError(@DbLookup(""; SF_ServeurSICl : SF_FichierSICl; "V_Clie20"; Inst_ClientNoFmt; 9); "");


v_Adresse_1 := @ReplaceSubstring(@Trim(v_Adresse1 + " " + v_Adresse2); "." : ","; "");
v_Adresse_02 := @Trim(@ReplaceSubstring(v_Adresse_1; "ave " : "Ave " : "boul " : "Boul "; "Avenue " : "Avenue " : "Boulevard " : "Boulevard "));
v_Adresse := @Implode(@Trim(v_Adresse_02 : v_Ville : v_Province : v_CodePostal : ("(" + @Trim(@ReplaceSubstring(Inst_ClientNom1 + " " + Inst_ClientNom2; "(" : ")"; "")) + ")")); "+");
v_Serti := "9430 Boulevard des Sciences+Anjou+QC+H1J 3B6+(Serti Informatique)";
"http://maps.google.ca/maps?q=de " + v_Serti + " à " + v_Adresse + "&iwloc=A&hl=fr"

